const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
const sanitizeName=v=>{const t=String(v??'').replace(/[\u0000-\u001f\u007f]/g,'').trim();return(t||'玩家').slice(0,12);};
const sanitizeChatText=v=>String(v??'').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g,'').trim().slice(0,100);
const escapeHtml=v=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function generateRoomCandidates(){const rooms=Array.from({length:90},(_,i)=>String(i+10));for(let i=rooms.length-1;i>0;i--){let j;try{const b=new Uint32Array(1);crypto.getRandomValues(b);j=b[0]%(i+1);}catch(_){j=Math.floor(Math.random()*(i+1));}[rooms[i],rooms[j]]=[rooms[j],rooms[i]];}return rooms;}
function isWallCell(c,r){if(c<0||r<0||c>=MAP_SIZE||r>=MAP_SIZE)return true;return MAP_DATA[r*MAP_SIZE+c]===1;}
function isNetworkWallCell(c,r){if(c<0||r<0||c>=NETWORK_MAP_SIZE||r>=NETWORK_MAP_SIZE)return true;return NETWORK_MAP_DATA[r*NETWORK_MAP_SIZE+c]===1;}
function doorsClosed(){return Number(gameState.doorLockUntil||0)>Date.now();}
function isDoorCell(c,r){return DOOR_CELL_SET.has(`${c},${r}`);}
function isNetworkDoorCell(c,r){return NETWORK_DOOR_CELL_SET.has(`${c},${r}`);}
function areaNameAt(x,y){const cell=MAP_SIZE/3;return AREA_NAMES[clamp(Math.floor(y/cell),0,2)][clamp(Math.floor(x/cell),0,2)];}
function circleHitsWall(x,y,r=COLLISION_RADIUS){const closed=doorsClosed(),nx=toNetworkCoord(x),ny=toNetworkCoord(y),nr=Math.max(NETWORK_PLAYER_RADIUS,toNetworkCoord(r)),minX=Math.floor(nx-nr),maxX=Math.floor(nx+nr),minY=Math.floor(ny-nr),maxY=Math.floor(ny+nr);for(let row=minY;row<=maxY;row++)for(let col=minX;col<=maxX;col++){if(!isNetworkWallCell(col,row)&&!(closed&&isNetworkDoorCell(col,row)))continue;const px=clamp(nx,col,col+1),py=clamp(ny,row,row+1),dx=nx-px,dy=ny-py;if(dx*dx+dy*dy<nr*nr)return true;}return false;}
function objById(id){return OBJECT_DEFS.find(o=>o.id===id)||null;}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}
function ventById(id){return VENT_DEFS.find(v=>v.id===id)||null;}
function sabotageDef(){return gameState.sabotage?SABOTAGE_DEFS[gameState.sabotage.type]||null:null;}

function applyTheme(theme,persist=true){document.documentElement.dataset.theme=theme;paletteTheme='';paletteCache=null;minimapBase=null;if(persist)try{localStorage.setItem('au-theme',theme);}catch(_){}const label=theme==='dark'?'浅色':'深色';menuThemeBtn.textContent=label;settingsBtn.textContent=label;}
function getInitialTheme(){try{const s=localStorage.getItem('au-theme');if(s==='light'||s==='dark')return s;}catch(_){}return document.documentElement.dataset.theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');}
function toggleTheme(){applyTheme((document.documentElement.dataset.theme||getInitialTheme())==='dark'?'light':'dark');}applyTheme(getInitialTheme(),false);
function setConnectionState(state,text){connectionStatus.dataset.state=state;connectionStatus.textContent=text;}
function setMenuStatus(text,type=''){menuStatus.textContent=text;menuStatus.className=type;}
function showToast(text,duration=1700){clearTimeout(toastTimer);gameToast.textContent=text;gameToast.classList.add('show');toastTimer=setTimeout(()=>gameToast.classList.remove('show'),duration);}
function showLeaveNotice(text){clearTimeout(leaveNoticeTimer);leaveNotice.textContent=text;leaveNotice.style.opacity='1';leaveNoticeTimer=setTimeout(()=>leaveNotice.style.opacity='0',1800);}
function checkOrientation(){rotateOverlay.classList.toggle('show',innerWidth<720&&innerHeight>innerWidth);}
function showMenu(){menu.style.display='flex';game.style.display='none';window._gameLoopRunning=false;}
function showGame(){menu.style.display='none';game.style.display='block';checkOrientation();resizeCanvas();}
function enterGame(){showGame();hudMyName.textContent=myName;roomIdDisplay.textContent=currentRoom;renderAllUI();lastFrameTime=performance.now();if(!window._gameLoopRunning){window._gameLoopRunning=true;requestAnimationFrame(gameLoop);}}
function sessionKey(room,name=myName){return 'au-dtam-resume:'+room+':'+encodeURIComponent(sanitizeName(name));}
function loadResumeToken(room){try{return localStorage.getItem(sessionKey(room))||sessionStorage.getItem('au-dtam-session:'+room)||'';}catch(_){return'';}}
function saveResumeToken(room,token){try{localStorage.setItem(sessionKey(room),token);sessionStorage.removeItem('au-dtam-session:'+room);}catch(_){}}
function clearResumeToken(room){try{localStorage.removeItem(sessionKey(room));sessionStorage.removeItem('au-dtam-session:'+room);}catch(_){}}

function normalizePlayers(raw){const out={};for(const p of Array.isArray(raw)?raw:Object.values(raw||{})){if(!p?.id)continue;const point=toClientPoint(p.pos||{x:75.5,y:75.5});out[String(p.id)]={id:String(p.id),name:sanitizeName(p.name),color:COLORS.includes(p.color)?p.color:COLORS[0],pos:{x:Number.isFinite(point.x)?point.x:toClientCoord(75.5),y:Number.isFinite(point.y)?point.y:toClientCoord(75.5)},isHost:!!p.isHost,connected:p.connected!==false,alive:p.alive!==false,inVent:!!p.inVent,animal:String(p.animal||'chicken'),disguiseTargetId:String(p.disguiseTargetId||''),abilityUntil:Number(p.abilityUntil||0),hiddenUntil:Number(p.hiddenUntil||0)};}return out;}
function normalizeBodies(raw){return(Array.isArray(raw)?raw:[]).map(b=>({...b,x:toClientCoord(b.x),y:toClientCoord(b.y)})).filter(b=>Number.isFinite(b.x)&&Number.isFinite(b.y));}
function normalizeProfiles(raw){const out={};for(const p of Array.isArray(raw)?raw:[]){if(!p?.id)continue;out[String(p.id)]={animal:String(p.animal||'chicken'),avatar:String(p.avatar||'')};}return out;}
function profileFor(id){return profiles[id]||{animal:players[id]?.animal||'chicken',avatar:''};}
function avatarMarkup(p){const pr=profileFor(p.id);return pr.avatar?'<img class="avatar-mini" src="'+escapeHtml(pr.avatar)+'" alt="">':'<span class="avatar-placeholder">'+escapeHtml((p.name||'?').slice(0,1))+'</span>';}
function avatarKey(name=myName){return 'au-dtam-avatar:'+encodeURIComponent(sanitizeName(name));}
const GLOBAL_AVATAR_KEY='au-dtam-avatar',SAVED_NAME_KEY='au-dtam-name';
function loadSavedName(){try{return sanitizeName(localStorage.getItem(SAVED_NAME_KEY)||'');}catch(_){return'玩家';}}
function saveName(name){try{localStorage.setItem(SAVED_NAME_KEY,sanitizeName(name));}catch(_){}}
function serverCompatibleAvatar(data){const value=String(data||'');return value.length<=MAX_AVATAR_CHARS&&/^data:image\/webp;base64,[A-Za-z0-9+/=]+$/.test(value)?value:'';}
function loadAvatar(name=myName){try{const global=serverCompatibleAvatar(localStorage.getItem(GLOBAL_AVATAR_KEY));if(global)return global;const legacy=serverCompatibleAvatar(localStorage.getItem(avatarKey(name)));if(legacy)localStorage.setItem(GLOBAL_AVATAR_KEY,legacy);else{localStorage.removeItem(GLOBAL_AVATAR_KEY);localStorage.removeItem(avatarKey(name));}return legacy;}catch(_){return'';}}
function saveAvatar(data,name=myName){try{const value=serverCompatibleAvatar(data);if(value){localStorage.setItem(GLOBAL_AVATAR_KEY,value);localStorage.setItem(avatarKey(name),value);}else{localStorage.removeItem(GLOBAL_AVATAR_KEY);localStorage.removeItem(avatarKey(name));}}catch(_){}}
function renderAvatarPreview(){const data=loadAvatar(sanitizeName(nameInput.value));avatarPreview.innerHTML=data?'<img src="'+escapeHtml(data)+'" alt="">':'头像';}
function syncAvatarProfile(){const avatar=loadAvatar(myName);if(socket&&socket.readyState===WebSocket.OPEN)sendPacket({t:'profile',avatar});}
async function processAvatarFile(file){if(!file||!file.type.startsWith('image/'))throw new Error('请选择图片文件');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(new Error('图片读取失败'));img.src=url;});const side=Math.min(img.naturalWidth,img.naturalHeight),sx=(img.naturalWidth-side)/2,sy=(img.naturalHeight-side)/2;for(const size of [56,48,40,36,32,28,24,20]){const c=document.createElement('canvas');c.width=c.height=size;const x=c.getContext('2d');x.imageSmoothingEnabled=true;x.imageSmoothingQuality='high';x.drawImage(img,sx,sy,side,side,0,0,size,size);for(const q of [.78,.66,.54,.42,.32]){const data=c.toDataURL('image/webp',q),valid=serverCompatibleAvatar(data);if(valid)return valid;}}throw new Error('头像压缩后仍然过大，或浏览器不支持 WebP');}finally{URL.revokeObjectURL(url);}}
function seedRemoteVisuals(){remoteVisuals={};for(const p of Object.values(players)){if(p.id===myPlayerId)continue;remoteVisuals[p.id]={x:p.pos.x,y:p.pos.y,targetX:p.pos.x,targetY:p.pos.y};}}
function retargetRemote(id,x,y){if(id===myPlayerId)return;const v=remoteVisuals[id];if(v){v.targetX=x;v.targetY=y;}else remoteVisuals[id]={x,y,targetX:x,targetY:y};}
function updateRemoteVisuals(dt){const a=1-Math.exp(-REMOTE_SMOOTHING*clamp(dt,0,0.05));for(const id in remoteVisuals){const v=remoteVisuals[id];v.x+=(v.targetX-v.x)*a;v.y+=(v.targetY-v.y)*a;}}

function renderPlayerCount(){playerCountNum.textContent=String(Object.values(players).filter(p=>p.connected).length||1);if(playerPanelVisible)renderPlayerPanel();}
function renderPlayerPanel(){const list=Object.values(players).sort((a,b)=>(b.isHost?1:0)-(a.isHost?1:0)||a.name.localeCompare(b.name)),revealDeaths=!selfState.alive||meetingUiActive()||gameState.phase==='ended';playerPanelBody.innerHTML=list.map(p=>{const me=p.id===myPlayerId,canKick=isHost&&!me&&gameState.phase==='lobby',showDead=revealDeaths&&!p.alive;return '<div class="player-row '+(showDead?'dead-row':'')+'">'+avatarMarkup(p)+'<span class="color-dot" style="background:'+escapeHtml(p.color)+'"></span><span class="player-name">'+escapeHtml(p.name)+(me?' · 你':'')+(p.connected?'':' · 离线')+'</span>'+(p.isHost?'<span class="host-badge">房主</span>':'')+(showDead?'<span class="dead-badge">死亡</span>':'')+(canKick?'<button type="button" class="kick-btn" data-player-id="'+escapeHtml(p.id)+'">移出</button>':'')+'</div>';}).join('')||'<div class="empty-msg">暂无玩家</div>';playerPanelBody.querySelectorAll('.kick-btn').forEach(btn=>btn.onclick=()=>kickPlayer(btn.dataset.playerId));}
function togglePlayerPanel(force){playerPanelVisible=typeof force==='boolean'?force:!playerPanelVisible;playerPanel.classList.toggle('open',playerPanelVisible);playerCountBtn.setAttribute('aria-expanded',String(playerPanelVisible));if(playerPanelVisible)renderPlayerPanel();}
function addMessage(name,text,time=Date.now(),meta={}){const clean=sanitizeChatText(text);if(!clean)return;messages.push({id:String(meta.id||''),name:sanitizeName(name),text:clean,time:Number(time||Date.now()),dead:meta.dead===true,channel:String(meta.channel||'room')});if(messages.length>80)messages.splice(0,messages.length-80);renderChatMessages();}
function renderChatMessages(){const row=m=>`<div class="msg-item ${m.dead?'ghost-msg':''}"><span class="msg-name">${m.dead?'幽灵 · ':''}${escapeHtml(m.name)}</span><span class="msg-text">${escapeHtml(m.text)}</span></div>`,rows=messages.map(row).join(''),html=rows||'<div class="empty-msg">暂无消息</div>';chatPanelMessages.innerHTML=html;chatStream.innerHTML=messages.slice(-3).map(row).join('')||'<div class="empty-msg">暂无消息</div>';chatPanelMessages.scrollTop=chatPanelMessages.scrollHeight;}
function meetingUiActive(){const m=gameState.meeting;return meetingOverlay.classList.contains('show')||(!!m&&['discussion','voting','result'].includes(String(m.stage||'')));}
function meetingChatOpen(){return meetingUiActive();}
function updateChatAvailability(){const inMeeting=meetingChatOpen(),canChat=gameState.phase!=='playing'||!selfState.alive||inMeeting;chatInput.disabled=!canChat;chatSend.disabled=!canChat;chatInput.placeholder=gameState.phase==='playing'?(selfState.alive?(inMeeting?'会议频道':'存活时只能在会议中发言'):'幽灵频道 · 仅死亡玩家可见'):'消息';}
function toggleChat(force){chatVisible=typeof force==='boolean'?force:!chatVisible;chatPanel.classList.toggle('open',chatVisible);chatPanel.setAttribute('aria-hidden',String(!chatVisible));chatToggle.setAttribute('aria-expanded',String(chatVisible));if(chatVisible)setTimeout(()=>chatInput.focus(),0);}

function renderStateUI(){renderPlayerCount();if(playerPanelVisible)renderPlayerPanel();renderGameMeta();renderLobby();renderActions();renderSabotagePanel();updateChatAvailability();if(selfState.inVent)renderVentPanel();if(infoMode)renderInfo();}
function renderAllUI(){renderStateUI();renderChatMessages();}
function renderGameMeta(){const displayPhase=meetingUiActive()?'meeting':gameState.phase,base=({lobby:'大厅',playing:'进行中',meeting:'会议',ended:'已结束'})[displayPhase]||displayPhase;phaseLabel.textContent=displayPhase==='playing'?base+' · '+areaNameAt(myPos.x,myPos.y):base;const meta=ROLE_META[selfState.role]||ROLE_META.crewmate;if(gameState.phase==='lobby')roleLabel.textContent='等待开始';else if(!selfState.alive&&selfState.ghostRole==='guardian')roleLabel.textContent='守护天使 · 幽灵';else roleLabel.textContent=meta.label+(selfState.alive?(selfState.inVent?' · 通风管':''):' · 已死亡');const pct=gameState.taskTotal?clamp(gameState.taskDone/gameState.taskTotal*100,0,100):0;taskProgress.style.width=pct+'%';const sab=gameState.sabotage,doorSec=Math.max(0,Math.ceil((Number(gameState.doorLockUntil||0)-Date.now())/1000));if(sab){const d=SABOTAGE_DEFS[sab.type];let text=d?.label||sab.type;if(sab.endsAt)text+=' · '+Math.max(0,Math.ceil((sab.endsAt-Date.now())/1000))+'s';if(Array.isArray(sab.requiredStations)&&sab.requiredStations.length>1)text+=' · '+(sab.fixedStations?.length||0)+'/'+sab.requiredStations.length;sabotageLine.hidden=false;sabotageLine.textContent=text;}else if(doorSec>0){sabotageLine.hidden=false;sabotageLine.textContent='门禁封锁 · '+doorSec+'s';}else sabotageLine.hidden=true;if(gameState.phase==='lobby')taskText.textContent='等待房主开始游戏';else if(gameState.phase==='ended')taskText.textContent=gameState.reason||'本局结束';else if(isCrewRole(selfState.role)){const remaining=selfState.tasks.filter(id=>!selfState.completed.includes(id));taskText.textContent=remaining.length?'剩余任务 '+remaining.length+' · '+remaining.map(id=>objById(id)?.label).filter(Boolean).slice(0,2).join(' / '):'你的任务已全部完成';}else if(isImpostorRole(selfState.role)){const fake=(selfState.fakeTasks||[]).map(id=>objById(id)?.label).filter(Boolean);taskText.textContent=selfState.alive?(fake.length?'伪装任务 · '+fake.slice(0,2).join(' / '):'隐藏身份并制造混乱'):'等待本局结束';}}
function syncRulesUI(){const st={...DEFAULT_SETTINGS,...(gameState.settings||{})},fields=[[ruleNormalImpostors,st.normalImpostors],[ruleShapeshifters,st.shapeshifters],[rulePhantoms,st.phantoms],[ruleVipers,st.vipers],[ruleEngineers,st.engineers],[ruleScientists,st.scientists],[ruleTrackers,st.trackers],[ruleNoisemakers,st.noisemakers],[ruleDetectives,st.detectives],[ruleGuardianAngels,st.guardianAngels],[ruleTasks,st.tasksPerCrew],[ruleSpeed,st.moveSpeed],[ruleKill,st.killCooldown],[ruleDiscussion,st.discussion],[ruleVoting,st.voting],[ruleEmergency,st.emergencyMeetings],[ruleSabotage,st.sabotageCooldown]];for(const [el,v] of fields){el.value=String(v??0);el.disabled=!isHost;}ruleConfirm.checked=!!st.confirmEjects;ruleConfirm.disabled=!isHost;const imp=Number(st.normalImpostors||0)+Number(st.shapeshifters||0)+Number(st.phantoms||0)+Number(st.vipers||0),crewSpecial=Number(st.engineers||0)+Number(st.scientists||0)+Number(st.trackers||0)+Number(st.noisemakers||0)+Number(st.detectives||0)+Number(st.guardianAngels||0);impRoleSummary.textContent='总数 '+imp;crewRoleSummary.textContent=crewSpecial?'特殊职业 '+crewSpecial+' · 其余普通船员':'其余为普通船员';}
function renderLobby(){const visible=gameState.phase==='lobby';lobbyPanel.classList.toggle('show',visible);if(!visible)return;const count=Object.values(players).filter(p=>p.connected).length;lobbyHint.textContent=isHost?`当前 ${count} 人 · 调整规则后开始`:`等待房主开始 · ${count} 人`;startGameBtn.style.display=isHost?'block':'none';startGameBtn.disabled=count<2;syncRulesUI();}
function nearestBody(){if(!selfState.alive||selfState.inVent||gameState.phase!=='playing')return null;let best=null,bestD=1.55*NETWORK_TO_CLIENT;for(const b of bodies){const d=Math.hypot(myPos.x-b.x,myPos.y-b.y);if(d<bestD){best=b;bestD=d;}}return best;}
function nearestKillTarget(){if(!isImpostorRole(selfState.role)||!selfState.alive||selfState.inVent||gameState.phase!=='playing')return null;let best=null,bestD=1.2*NETWORK_TO_CLIENT;for(const p of Object.values(players)){if(p.id===myPlayerId||!p.alive||!p.connected||p.inVent||(selfState.allies||[]).includes(p.id))continue;const v=remoteVisuals[p.id],pos=v?{x:v.x,y:v.y}:p.pos;const d=dist(myPos,pos);if(d<bestD){best=p;bestD=d;}}return best;}
function nearestAbilityTarget(){if(gameState.phase!=='playing'||selfState.inVent)return null;const role=selfState.role,guardian=!selfState.alive&&selfState.ghostRole==='guardian';if(!selfState.alive&&!guardian)return null;if(['phantom','scientist'].includes(role))return null;if(!['shapeshifter','tracker','detective'].includes(role)&&!guardian)return null;const maxD=(guardian?2.2:1.8)*NETWORK_TO_CLIENT;let best=null,bestD=maxD;for(const p of Object.values(players)){if(p.id===myPlayerId||!p.alive||!p.connected||p.inVent)continue;const v=remoteVisuals[p.id],px=v?v.x:p.pos.x,py=v?v.y:p.pos.y,d=Math.hypot(myPos.x-px,myPos.y-py);if(d<bestD){best=p;bestD=d;}}return best;}
function nearestAssignedTask(){if(!isCrewRole(selfState.role)||selfState.inVent||gameState.phase!=='playing')return null;let best=null,bestD=1.65*NETWORK_TO_CLIENT;for(const id of selfState.tasks){if(selfState.completed.includes(id))continue;const o=objById(id);if(!o)continue;const d=dist(myPos,o);if(d<bestD){best=o;bestD=d;}}return best;}
function nearestSabotageStation(){const sab=gameState.sabotage,d=sabotageDef();if(!sab||!d||!selfState.alive||selfState.inVent)return null;let best=null,bestD=1.75*NETWORK_TO_CLIENT;for(const id of d.stations){if(sab.fixedStations?.includes(id))continue;const o=objById(id);if(o&&dist(myPos,o)<bestD){best=o;bestD=dist(myPos,o);}}return best;}
function nearestVent(){if(!(isImpostorRole(selfState.role)||selfState.role==='engineer')||!selfState.alive||selfState.inVent||gameState.phase!=='playing')return null;let best=null,bestD=1.15*NETWORK_TO_CLIENT;for(const v of VENT_DEFS){const d=dist(myPos,v);if(d<bestD){best=v;bestD=d;}}return best;}
function nearbyInfo(){if(!selfState.alive||selfState.inVent||gameState.phase!=='playing')return null;let best=null,bestD=1.65*NETWORK_TO_CLIENT;for(const [id,mode] of Object.entries(INFO_STATIONS)){const o=objById(id);if(o&&dist(myPos,o)<bestD){best={...o,mode};bestD=dist(myPos,o);}}return best;}
function claimAction(ms=260){const now=Date.now();if(now<actionLockUntil)return false;actionLockUntil=now+ms;return true;}
function activateInteract(){if(!claimAction())return;const repair=nearestSabotageStation(),task=nearestAssignedTask();if(repair){openRepair(repair);return;}if(task){openTask(task);return;}if(canEmergency())sendPacket({t:'emergency'});}
function activateVent(){if(!claimAction())return;if(selfState.inVent){renderVentPanel();return;}const vent=nearestVent();if(vent)sendPacket({t:'vent',action:'enter',ventId:vent.id});}
function activateInfo(){if(!claimAction())return;const info=nearbyInfo();if(info)openInfo(info.mode);}

function canEmergency(){if(!selfState.alive||selfState.inVent||gameState.phase!=='playing'||selfState.emergencyUsed>=(gameState.settings?.emergencyMeetings??1)||gameState.sabotage)return false;const o=objById(EMERGENCY_STATION);return o&&dist(myPos,o)<1.6*NETWORK_TO_CLIENT;}
