function renderInfo(){if(!infoMode)return;if(infoMode==='cams'){const feeds=[['西北',16,16],['东北',84,16],['西南',16,84],['东南',84,84]],rows=feeds.map(([name,x,y])=>{const seen=[];for(const id in players){const p=players[id];if(p.connected&&p.alive&&!p.inVent&&Math.hypot(p.pos.x-x,p.pos.y-y)<18)seen.push(p);}return{name,seen};}),sig='c:'+rows.map(r=>r.name+':'+r.seen.map(p=>p.id).sort().join(',')).join('|');if(sig===lastInfoSignature)return;lastInfoSignature=sig;infoBody.innerHTML=`<div class="camera-grid">${rows.map(r=>`<div class="camera-feed"><strong>${r.name}</strong><div>${r.seen.length?r.seen.map(p=>`<span class="camera-person"><i style="background:${escapeHtml(p.color)}"></i>${escapeHtml(p.name)}</span>`).join(''):'无人'}</div></div>`).join('')}</div>`;return;}const grid=5,cell=MAP_SIZE/grid,counts=Array.from({length:grid*grid},()=>({alive:0,bodies:0}));for(const id in players){const p=players[id];if(!p.connected||!p.alive||p.inVent)continue;const sx=clamp(Math.floor(p.pos.x/cell),0,grid-1),sy=clamp(Math.floor(p.pos.y/cell),0,grid-1);counts[sy*grid+sx].alive++;}for(const b of bodies){const sx=clamp(Math.floor(b.x/cell),0,grid-1),sy=clamp(Math.floor(b.y/cell),0,grid-1);counts[sy*grid+sx].bodies++;}const sig='a:'+counts.map(c=>`${c.alive}.${c.bodies}`).join(',');if(sig===lastInfoSignature)return;lastInfoSignature=sig;infoBody.innerHTML=`<div class="admin-grid">${counts.map((c,i)=>`<div class="admin-cell ${c.alive||c.bodies?'active':''}"><span>${String.fromCharCode(65+(i%grid))}${Math.floor(i/grid)+1}</span><strong>${c.alive+c.bodies}</strong>${c.bodies?'<small>含静止信号</small>':''}</div>`).join('')}</div>`;}
function ensureMinimapBase(){if(minimapBase)return minimapBase;const c=document.createElement('canvas');c.width=c.height=300;const x=c.getContext('2d'),s=300/MAP_SIZE;x.fillStyle=document.documentElement.dataset.theme==='dark'?'#11151a':'#f5f6f7';x.fillRect(0,0,300,300);x.fillStyle=document.documentElement.dataset.theme==='dark'?'#3b4551':'#9da7b4';for(let row=0;row<MAP_SIZE;row++)for(let col=0;col<MAP_SIZE;col++)if(isWallCell(col,row))x.fillRect(Math.floor(col*s),Math.floor(row*s),Math.ceil(s),Math.ceil(s));minimapBase=c;return c;}
function drawMinimap(){if(!minimapOverlay.classList.contains('show'))return;const x=minimapCanvas.getContext('2d'),base=ensureMinimapBase(),s=300/MAP_SIZE,now=Date.now();x.clearRect(0,0,300,300);x.drawImage(base,0,0);const ids=isCrewRole(selfState.role)?selfState.tasks:(selfState.fakeTasks||[]);x.fillStyle='#2563eb';for(const id of ids){if(selfState.completed.includes(id))continue;const o=objById(id);if(o)x.fillRect(Math.round(o.x*s)-4,Math.round(o.y*s)-4,8,8);}if(gameState.sabotage){x.fillStyle='#dc2626';for(const id of gameState.sabotage.requiredStations||[]){if(gameState.sabotage.fixedStations?.includes(id))continue;const o=objById(id);if(o)x.fillRect(Math.round(o.x*s)-5,Math.round(o.y*s)-5,10,10);}}if(selfState.role==='tracker'&&selfState.trackedId&&Number(selfState.trackUntil||0)>now){const p=players[selfState.trackedId],v=p&&remoteVisuals[p.id],px=v?v.x:p?.pos?.x,py=v?v.y:p?.pos?.y;if(Number.isFinite(px)&&Number.isFinite(py)){x.strokeStyle='#f59e0b';x.lineWidth=3;x.strokeRect(Math.round(px*s)-6,Math.round(py*s)-6,12,12);}}if(noisemakerPing&&noisemakerPing.until>now){x.strokeStyle='#dc2626';x.lineWidth=3;x.strokeRect(Math.round(noisemakerPing.x*s)-7,Math.round(noisemakerPing.y*s)-7,14,14);}x.fillStyle='#f8fafc';x.fillRect(Math.round(myPos.x*s)-3,Math.round(myPos.y*s)-3,6,6);x.strokeStyle='#111827';x.strokeRect(Math.round(myPos.x*s)-4,Math.round(myPos.y*s)-4,8,8);}
