async function voiceApi(path,method='POST',payload){const url=VOICE_API+path+(path.includes('?')?'&':'?')+'room='+encodeURIComponent(currentRoom),headers={'x-dtam-token':resumeToken};let body;if(payload!==undefined){headers['content-type']='application/json';body=JSON.stringify(payload);}const r=await fetch(url,{method,headers,body});let data={};try{data=await r.json();}catch(_){}if(!r.ok||data.errorCode)throw new Error(data.errorDescription||data.error||('语音服务 '+r.status));return data;}
function scheduleVoiceRestart(){if(!voiceDesired||voiceRestartTimer)return;voiceRestartTimer=setTimeout(()=>{voiceRestartTimer=null;if(voiceDesired)rebuildVoiceTransport().catch(e=>showToast('语音重连失败：'+e.message,1800));},1800);}
function watchVoicePc(pc){const check=()=>{const bad=['failed','closed'].includes(pc.connectionState)||pc.iceConnectionState==='failed';if(bad)scheduleVoiceRestart();else if(pc.connectionState==='disconnected'||pc.iceConnectionState==='disconnected'){clearTimeout(voiceDisconnectTimer);voiceDisconnectTimer=setTimeout(()=>{if(pc.connectionState==='disconnected'||pc.iceConnectionState==='disconnected')scheduleVoiceRestart();},3000);}};pc.addEventListener('connectionstatechange',check);pc.addEventListener('iceconnectionstatechange',check);}
function newVoicePc(){const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.cloudflare.com:3478'}],bundlePolicy:'max-bundle'});watchVoicePc(pc);return pc;}
function clearRemoteVoice(){for(const a of voiceRemoteAudios.values()){try{a.srcObject=null;a.remove();}catch(_){}}voiceRemoteAudios.clear();voiceSubscribed.clear();voicePendingMids.clear();voiceSink.innerHTML='';}
function voicePeerAllowed(v){const p=players[String(v?.playerId||'')];if(!p)return false;if(gameState.phase==='lobby'||gameState.phase==='ended')return true;return selfState.alive?p.alive:true;}
function pruneVoiceDirectory(){const active=new Set(voiceDirectory.filter(v=>v.playerId!==myPlayerId&&v.enabled&&v.connected&&v.sessionId&&v.trackName&&voicePeerAllowed(v)).map(v=>v.sessionId+'|'+v.trackName));for(const [key,a] of voiceRemoteAudios){if(!active.has(key)){try{a.srcObject=null;a.remove();}catch(_){}voiceRemoteAudios.delete(key);voiceSubscribed.delete(key);}}for(const key of [...voiceSubscribed.keys()])if(!active.has(key))voiceSubscribed.delete(key);}
function refreshVoicePrivacy(){if(!voiceActive)return;pruneVoiceDirectory();scheduleVoiceDirectory();}
async function unlockVoicePlayback(){let blocked=false;for(const a of voiceRemoteAudios.values()){try{await a.play();}catch(_){blocked=true;}}voiceUnlockBtn.hidden=!blocked;}
async function pullVoiceDirectory(){if(!voiceActive||!voiceRecvPc||!voiceRecvSession)return;pruneVoiceDirectory();const pending=voiceDirectory.filter(v=>v.playerId!==myPlayerId&&v.enabled&&v.connected&&v.sessionId&&v.trackName&&voicePeerAllowed(v)&&!voiceSubscribed.has(v.sessionId+'|'+v.trackName));if(!pending.length)return;const res=await voiceApi('/sessions/'+encodeURIComponent(voiceRecvSession)+'/tracks/new','POST',{tracks:pending.map(v=>({location:'remote',sessionId:v.sessionId,trackName:v.trackName}))});(res.tracks||[]).forEach((tr,i)=>{if(pending[i])voicePendingMids.set(String(tr.mid),pending[i]);});if(res.requiresImmediateRenegotiation&&res.sessionDescription){await voiceRecvPc.setRemoteDescription(res.sessionDescription);const answer=await voiceRecvPc.createAnswer();await voiceRecvPc.setLocalDescription(answer);await voiceApi('/sessions/'+encodeURIComponent(voiceRecvSession)+'/renegotiate','PUT',{sessionDescription:{sdp:answer.sdp,type:'answer'}});}pending.forEach(v=>voiceSubscribed.set(v.sessionId+'|'+v.trackName,v.playerId));}
