    isHost=!!players[myPlayerId]?.isHost;if(msg.game)gameState={...gameState,...msg.game,settings:{...DEFAULT_SETTINGS,...(msg.game.settings||gameState.settings||{})}};if(msg.selfState)selfState={...selfState,...msg.selfState};if(Array.isArray(msg.bodies))bodies=normalizeBodies(msg.bodies);if(gameState.meeting&&!meetingOverlay.classList.contains('show'))openMeeting({meeting:gameState.meeting});refreshVoicePrivacy();renderStateUI();return;
