  if(msg.t==='correct'){const x=toClientCoord(msg.x),y=toClientCoord(msg.y);if(Number.isFinite(x)&&Number.isFinite(y)){myPos={x,y};if(players[myPlayerId])players[myPlayerId].pos={...myPos};posDirty=false;}return;}
  if(msg.t==='game_start'){gameState={...gameState,...msg.game,settings:{...DEFAULT_SETTINGS,...(msg.game?.settings||{})},phase:'playing',meeting:null};reportBlockedUntil=0;selfState={...selfState,...msg.selfState};bodies=[];if(players[myPlayerId])players[myPlayerId].alive=true;refreshVoicePrivacy();hideEnd();closeMeeting();renderAllUI();showRoleReveal();return;}
