function connectRoom(room,create=false,reconnect=false){room=String(room).replace(/\D/g,'').slice(0,2);if(!ROOM_CODE_RE.test(room))return Promise.reject(new Error('房间号应为 2 位数字'));currentRoom=room;if(!resumeToken&&!create)resumeToken=loadResumeToken(room);intentionalClose=false;const generation=++socketGeneration;if(socket){try{socket.onclose=null;socket.close();}catch(_){}}setConnectionState('connecting',reconnect?'重连中':'连接中');if(!reconnect)setMenuStatus(create?'正在创建房间…':'正在加入房间…');const params=new URLSearchParams({room,name:myName,create:create?'1':'0',v:CLIENT_VERSION});if(resumeToken)params.set('token',resumeToken);const ws=new WebSocket(`${REALTIME_ORIGIN}/ws?${params}`);socket=ws;return new Promise((resolve,reject)=>{connectResolve=resolve;connectReject=reject;connectTimeout=setTimeout(()=>{if(generation!==socketGeneration)return;try{ws.close();}catch(_){}reject(new Error('连接超时，请稍后重试'));connectResolve=null;connectReject=null;},10000);ws.onopen=()=>{if(generation!==socketGeneration)return;lastPongAt=Date.now();startHeartbeat();};ws.onmessage=e=>{if(generation===socketGeneration)handleServerMessage(e.data);};ws.onerror=()=>{};ws.onclose=()=>{if(generation!==socketGeneration)return;stopHeartbeat();if(connectReject){const r=connectReject;clearTimeout(connectTimeout);connectResolve=null;connectReject=null;r(new Error('无法连接到实时服务器'));}if(!intentionalClose&&currentRoom&&game.style.display!=='none')scheduleReconnect();else if(!intentionalClose&&menu.style.display!=='none')setConnectionState('error','连接失败');};});}
function scheduleReconnect(){if(intentionalClose||!currentRoom||reconnectTimer)return;reconnectAttempts++;const delay=Math.min(8000,500*Math.pow(2,Math.min(reconnectAttempts-1,4)));setConnectionState('connecting',`重连中 ${reconnectAttempts}`);showToast('连接中断，正在自动恢复…',1400);reconnectTimer=setTimeout(async()=>{reconnectTimer=null;if(intentionalClose||!currentRoom)return;try{await connectRoom(currentRoom,false,true);}catch(_){if(!intentionalClose)scheduleReconnect();}},delay);}
async function createRoom(){createBtn.disabled=joinBtn.disabled=true;resumeToken='';let collisions=0;for(const room of generateRoomCandidates()){try{await connectRoom(room,true,false);createBtn.disabled=joinBtn.disabled=false;return;}catch(err){if(String(err.message).includes('已存在')){collisions++;continue;}setMenuStatus(err.message,'error');break;}}if(collisions>0)setMenuStatus('两位房间号暂时都很拥挤，请稍后重试','error');createBtn.disabled=joinBtn.disabled=false;}
async function joinRoom(room){createBtn.disabled=joinBtn.disabled=true;resumeToken=loadResumeToken(room);try{await connectRoom(room,false,false);}catch(err){setMenuStatus(err.message,'error');}createBtn.disabled=joinBtn.disabled=false;}
