function update(dt){dt=clamp(dt,0,0.05);if(!socket||socket.readyState!==WebSocket.OPEN||!myPlayerId)return;const perfNow=performance.now();if(perfNow-lastUiRefresh>=UI_REFRESH_MS){lastUiRefresh=perfNow;renderActions();renderGameMeta();for(const id in visualTaskEffects)if(visualTaskEffects[id]<=Date.now())delete visualTaskEffects[id];}if(gameState.phase!=='playing'||meetingOverlay.classList.contains('show')||selfState.inVent||taskModal.classList.contains('show')||sabotageOverlay.classList.contains('show')||infoOverlay.classList.contains('show'))return;let dx=0,dy=0;if(keys.ArrowUp||keys.w||keys.W)dy-=1;if(keys.ArrowDown||keys.s||keys.S)dy+=1;if(keys.ArrowLeft||keys.a||keys.A)dx-=1;if(keys.ArrowRight||keys.d||keys.D)dx+=1;if(joyActive){dx+=joyDX;dy+=joyDY;}const mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag;}if(Math.abs(dx)>0.001||Math.abs(dy)>0.001){const speed=Number(gameState.settings?.moveSpeed||4.6)*NETWORK_TO_CLIENT,step=speed*dt,nx=clamp(myPos.x+dx*step,COLLISION_RADIUS,MAP_SIZE-COLLISION_RADIUS);if(!selfState.alive||!circleHitsWall(nx,myPos.y))myPos.x=nx;const ny=clamp(myPos.y+dy*step,COLLISION_RADIUS,MAP_SIZE-COLLISION_RADIUS);if(!selfState.alive||!circleHitsWall(myPos.x,ny))myPos.y=ny;if(players[myPlayerId])players[myPlayerId].pos={...myPos};posDirty=true;}if(posDirty&&performance.now()-lastPosSendTime>=POS_SEND_INTERVAL){sendPacket({t:'pos',x:+toNetworkCoord(myPos.x).toFixed(3),y:+toNetworkCoord(myPos.y).toFixed(3)});lastPosSendTime=performance.now();posDirty=false;}}
