function drawPixelAnimal(x,y,r,color,animal,outline){const u=Math.max(1,Math.round(r/5));x=Math.round(x);y=Math.round(y);ctx.fillStyle=outline;ctx.fillRect(x-4*u,y-3*u,8*u,7*u);ctx.fillStyle=color;ctx.fillRect(x-3*u,y-2*u,6*u,5*u);ctx.fillRect(x-2*u,y-4*u,4*u,3*u);ctx.fillStyle='#111827';ctx.fillRect(x+u,y-3*u,u,u);if(animal==='chicken'){ctx.fillStyle='#f59e0b';ctx.fillRect(x+2*u,y-2*u,2*u,u);ctx.fillStyle='#ef4444';ctx.fillRect(x-u,y-5*u,u,u);ctx.fillRect(x,y-5*u,u,u);}else if(animal==='rabbit'){ctx.fillStyle=color;ctx.fillRect(x-2*u,y-7*u,2*u,4*u);ctx.fillRect(x+u,y-7*u,2*u,4*u);ctx.fillStyle='#f9a8d4';ctx.fillRect(x-u,y-6*u,u,2*u);ctx.fillRect(x+u,y-6*u,u,2*u);}else if(animal==='cat'){ctx.fillStyle=color;ctx.fillRect(x-3*u,y-5*u,2*u,2*u);ctx.fillRect(x+u,y-5*u,2*u,2*u);ctx.fillRect(x+3*u,y,u,3*u);}else if(animal==='raccoon'){ctx.fillStyle='#374151';ctx.fillRect(x-2*u,y-3*u,4*u,u);ctx.fillRect(x+3*u,y,u,3*u);ctx.fillStyle='#9ca3af';ctx.fillRect(x+4*u,y+u,2*u,u);}else if(animal==='goat'){ctx.fillStyle='#d1d5db';ctx.fillRect(x-3*u,y-6*u,u,3*u);ctx.fillRect(x+2*u,y-6*u,u,3*u);ctx.fillStyle=color;ctx.fillRect(x+3*u,y+u,2*u,u);}else{ctx.fillStyle=color;ctx.fillRect(x-3*u,y-5*u,2*u,2*u);ctx.fillRect(x+u,y-5*u,2*u,2*u);ctx.fillRect(x+3*u,y,3*u,2*u);ctx.fillStyle='#f8fafc';ctx.fillRect(x+4*u,y+u,2*u,u);}ctx.fillStyle=outline;ctx.fillRect(x-3*u,y+3*u,2*u,u);ctx.fillRect(x+u,y+3*u,2*u,u);}
